/**
 * `RING5_AIRPORT_NAMES`'teki havalimanlarının hizmet verdiği şehir, iki dilde. Kurallar
 * `FOREIGN_AIRPORT_CITIES` ve `RING4_AIRPORT_CITIES`'tekilerdir (Türkçe şehir Türkçe adın içindeki
 * yer adıdır; ham OurAirports yerleşimi yabancı havalimanında gösterilmez). 5. halkada genelleşen
 * kararlar:
 * - İngilizce şehir, şehrin İngilizcede yerleşik adıdır; Türkçe şehir Türkçe adın içindeki biçimdir
 *   (Pekin / Beijing, Seul / Seoul, Meksiko / Mexico City, Guatemala / Guatemala City, Panama /
 *   Panama City, Ho Chi Minh Kenti / Ho Chi Minh City, Paskalya Adası / Rapa Nui, Chatham Adaları /
 *   Chatham Islands, Nikolayevsk-na-Amure / Nikolayevsk-on-Amur).
 * - OurAirports yerleşimi tüzel kişiliği olmayan bir yer, semt, ilçe ya da havalimanının kendi
 *   adının kopyasıysa şehir hizmet verilen yerdir (Gwinn → Marquette, Savoy → Champaign,
 *   Freeland → Saginaw, Beringin → Medan, Seletar → Singapur, La Isabela → Santo Domingo, Tinson
 *   Pen → Kingston, Gurney → Alotau). Birden çok şehre hizmet eden havalimanında şehir, IATA şehri
 *   olan kontluk ya da bölge merkezidir (Saginaw, Staunton, Kitchener).
 * - Tek havalimanlı adada resmî ad adayı taşıyorsa şehir adadır, köy ya da kasaba yazılmaz
 *   (4. halka kuralı: Marie-Galante, Virgin Gorda, Mustique, Exuma, Inagua, Boa Vista, São Nicolau,
 *   São Vicente, Anjouan, Mangareva, Miyako).
 * - Ülke ya da bölge adını taşıyan havalimanında şehir başkenttir ve Türkçe adda geçmez
 *   (Fort-de-France, Flying Fish Cove, Kingston, West Island, Majuro, Yaren, Alofi, Bandar Seri
 *   Begawan, San Salvador, Georgetown).
 * - Büyük bir şehrin metro grubunda şehir alanı büyük şehirdir (New York, Washington, Chicago,
 *   Tokyo, Osaka, Pekin, Şanghay, Meksiko, São Paulo, Buenos Aires, Montréal, Melbourne); büyük
 *   şehrin adını taşıyan ya da onun metro grubundaki uzak havalimanında şehir yerel kasabadır
 *   (Sanford, Rockford, Avalon, Gatineau, Newburgh, Everett, Narita, Campinas, Subang).
 * - Çin'de il düzeyi şehir adı adda geçiyorsa şehir odur, özerk vilayet adlı havalimanında ilçedir
 *   (Shangri-La, Mangshi, Xiahe, Jinghong, Songpan). Kaynakta olan uzun ünlü işareti şehirde kalır
 *   (Ōzora), şehir havalimanı adındaki işaretsiz yazımdan geliyorsa eklenmez (Kitadaito, Sondok).
 *
 * Tablo, ad tablosu gibi düz nesne değişmezidir (D-102).
 */
